ins(8,"Растрові редактори",[
R("Для чого дизайнеру растровий редактор",["flow",["Фото","Ретуш і корекція","Колаж","Підготовка до публікації"]],
 "Растровий редактор потрібен там, де працюємо з фотографіями й «живими» зображеннями. Типові завдання: <b>ретуш</b> портретів, <b>корекція</b> кольору й світла, <b>колажі</b> та фотоманіпуляції, створення <b>банерів, обкладинок</b>, макетів сайтів, <b>цифровий живопис</b> та підготовка зображень до друку чи публікації в мережі.<br><br>Професійний редактор об’єднує десятки інструментів в одному вікні й дозволяє працювати <b>неруйнівно</b>: правки зберігаються окремо від оригінальних пікселів, і їх можна змінювати будь-коли.",
 ["Ретуш, корекція, колаж, макети","Цифровий живопис і підготовка до друку","Неруйнівна робота – головна перевага"],"Професійні ретушери витрачають на один обкладинковий портрет кілька годин, і більшість часу – на дрібні локальні правки.","Завдання"),
R("Порівняння популярних редакторів",["vs",["Photoshop",["Стандарт індустрії","Платна підписка","Багато коригувань, шарів, фільтрів"]],["GIMP, Krita, Photopea",["Безкоштовні","Схожі інструменти, трохи інший інтерфейс","Для навчання й більшості завдань достатньо"]]],
 "Серед безкоштовних програм <b>GIMP</b> – потужний редактор із відкритим кодом, <b>Krita</b> створена для цифрового малювання, <b>Photopea</b> працює у браузері й дуже схожа на Photoshop. <b>Affinity</b> (від Canva) – безкоштовна альтернатива без підписки, для входу потрібен обліковий запис Canva. На телефоні популярні <b>Snapseed</b> та <b>Lightroom Mobile</b>.<br><br>Принципи роботи в усіх редакторах схожі: шари, виділення, маски, коригування, фільтри. Якщо ти розумієш ці принципи, перейти з однієї програми на іншу можна за кілька годин. Саме тому ми вчимо не кнопки, а логіку роботи.",
 ["GIMP, Krita, Photopea – безкоштовні","Принципи однакові в усіх редакторах","Вивчай логіку, а не кнопки"],"Photopea зберігає й відкриває файли PSD, тож це добрий запасний варіант, коли немає Photoshop.","Вибір"),
R("Меню Photoshop: що де знаходиться",["tree","Меню",[["Файл",["Створити, відкрити, зберегти, експорт"]],["Зображення",["Режим, розмір, корекція"]],["Шар",["Нові шари, маски, об’єднання"]],["Фільтр",["Розмиття, різкість, шум, стилізація"]]]],
 "Меню <b>Файл</b> відповідає за документи: створити, відкрити, зберегти, експортувати. <b>Редагувати</b> містить скасування, копіювання, заливку й вільне трансформування. У меню <b>Зображення</b> змінюють режим, розмір зображення й полотна та застосовують корекції. <b>Шар</b> – це все про шари, а <b>Текст</b> – про оформлення тексту. <b>Виділити</b> керує виділеннями, <b>Фільтр</b> містить ефекти, <b>Перегляд</b> – масштаб, лінійки й напрямні, <b>Вікно</b> – відкриття панелей.<br><br>Багато команд мають гарячі клавіші, які варто вивчати поступово: Ctrl+Z скасовує дію, Ctrl+S зберігає, Ctrl+Alt+Z крок назад по історії.",
 ["Зображення – режим, розмір, корекція","Шар – усе про шари","Вікно – вмикає панелі"],"Панель «Журнал історії» дозволяє повернутися на багато кроків назад, а не лише на один.","Меню"),
R("Одиниці та поле зору: лінійки, сітка, напрямні",["flow",["Перегляд → Лінійки","Перетягни напрямну","Прив’язка до напрямних","Сітка для вирівнювання"]],
 "Щоб розмістити елементи точно, використовують допоміжні засоби. <b>Лінійки</b> (Ctrl+R) показують координати в обраних одиницях – пікселях, міліметрах чи дюймах. <b>Напрямні</b> витягуються з лінійок мишею й діють як невидимі лінії, до яких притягуються об’єкти. <b>Сітка</b> (Ctrl+') розкреслює полотно рівними клітинками.<br><br>Для макета сайту краще працювати в пікселях, для друку – в міліметрах. Одиниці вимірювання змінюють у налаштуваннях програми або клацанням правою кнопкою на лінійці.",
 ["Ctrl+R – лінійки","Напрямні притягують об’єкти","Одиниці залежать від мети: px чи мм"],"Макетувальники використовують сітку з кроком 8 пікселів: так усі відступи вийдуть кратними.","Точність"),
R("Історія та скасування дій",["flow",["Ctrl+Z","Ctrl+Alt+Z","Панель «Історія»","Знімок стану"]],
 "Помилитися при роботі нормально. У Photoshop <b>Ctrl+Z</b> скасовує останню дію, а <b>Ctrl+Alt+Z</b> крок за кроком повертається назад. Панель <b>«Журнал історії»</b> показує список виконаних кроків: клікнувши по будь-якому, повертаєшся до цього стану. Можна створити <b>знімок</b> поточного стану й порівнювати «до» і «після».<br><br>Але кількість кроків історії обмежена, а після закриття файлу вона зникає. Тому рятує <b>збереження версій</b>: file_v1.psd, file_v2.psd, і неруйнівні прийоми – шари, маски, коригувальні шари.",
 ["Ctrl+Z – одна дія, Ctrl+Alt+Z – багато","Історія зникає після закриття файлу","Зберігай версії файлу"],"За замовчуванням Photoshop пам’ятає 50 кроків історії, але цю цифру можна збільшити в налаштуваннях.","Скасування")]);

